@extends('layouts.app',['title'=>'Examinations']) @section('content')<div class="heading"><div><div class="eyebrow">Assessment & Punjab Board results</div><h1>Examinations</h1></div><button class="button">＋ New examination</button></div>@if(session('success'))<div style="padding:14px;background:#e8f8ee;color:#237a46;border-radius:11px;margin-bottom:16px">{{session('success')}}</div>@endif @error('publish')<div style="padding:14px;background:#fff0f0;color:#b43b4b;border-radius:11px;margin-bottom:16px">{{$message}}</div>@enderror @foreach($exams as $exam)<div class="card panel" style="margin-bottom:16px"><div class="panel-title"><div><h3>{{$exam->name}}</h3><div class="eyebrow" style="margin-top:5px">{{$exam->starts_on->format('d M')}} – {{$exam->ends_on->format('d M Y')}} · {{$exam->components_count}} assessment components</div></div><span class="badge">{{ucwords(str_replace('_',' ',$exam->status))}}</span></div><div style="display:flex;gap:10px;flex-wrap:wrap">@foreach($exam->components()->with(['subject','gradeLevel'])->get() as $component)<a href="{{route('assessments.entry',$component)}}" style="padding:13px;border:1px solid #e5e8f0;border-radius:10px;color:#172038;text-decoration:none"><strong>{{$component->subject->name}}</strong><br><small class="eyebrow">{{$component->gradeLevel->name}} · {{$component->max_marks}} marks</small></a>@endforeach</div>@if($exam->status!=='published')<form method="post" action="{{route('exams.publish',$exam)}}" style="margin-top:18px">@csrf<button class="button" style="background:#172038">Publish results</button></form>@endif</div>@endforeach @endsection
